using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

var blobUri = new Uri("https://demostorageaccount.blob.core.windows.net");
var credential = new DefaultAzureCredential();
var serviceClient = new BlobServiceClient(blobUri, credential);

var container = serviceClient.GetBlobContainerClient("uploads");
await container.CreateIfNotExistsAsync(PublicAccessType.None);

// Upload
var blob = container.GetBlobClient("report-2024.pdf");
await blob.UploadAsync("report.pdf", overwrite: true);

// Download
var download = await blob.DownloadAsync();
using var stream = File.OpenWrite("report-copy.pdf");
await download.Value.Content.CopyToAsync(stream);

await foreach (var blobItem in container.GetBlobsAsync())
{
    Console.WriteLine($"{blobItem.Name} - {blobItem.Properties.ContentLength} bytes");
}

await blob.DeleteIfExistsAsync(DeleteSnapshotsOption.IncludeSnapshots);

var sasBuilder = new BlobSasBuilder
{
    BlobContainerName = container.Name,
    BlobName = blob.Name,
    Resource = "b",
    ExpiresOn = DateTimeOffset.UtcNow.AddHours(1)
};

sasBuilder.SetPermissions(BlobSasPermissions.Read);

var sasUri = blob.GenerateSasUri(sasBuilder);
Console.WriteLine(sasUri);
